#!/usr/bin/env bash
# Benchmark: single-quoted vs double-quoted literal pattern search in bash.
#
# Both modes search for the same absent pattern inside a large subject string.
# The quote style of the inline literal pattern is the only variable:
#
#   single-quoted  *'PATTERN'*  — bash scans only for the closing apostrophe
#   double-quoted  *"PATTERN"*  — bash scans every character for $ ` \ !
#                                 (none present; no substitution occurs)
#
# Because the pattern is an inline literal inside the loop body, bash re-processes
# the quoted word on every iteration, so the scanning overhead accumulates.
#
# Usage: benchmark.sh --mode {single|double} [--size N] [--min-runtime T]
#   --size N         iterations per block (default 10000)
#   --min-runtime T  minimum wall-clock seconds (default 1.0)

set -euo pipefail

MODE="single"
SIZE=10000

while [[ $# -gt 0 ]]; do
    case "$1" in
        --mode)        MODE="$2";        shift 2 ;;
        --size)        SIZE="$2";          shift 2 ;;
        *)             printf 'Unknown option: %s\n' "$1" >&2; exit 1 ;;
    esac
done


emit_metric() {
    printf '%s search_iterations=%d\n' "$(date +%s%N)" "$1"
}

run_single() {
    local i=0
    local newvar

    while (( i < SIZE )); do
        # Single-quoted literal: bash extracts content by scanning only for '
        newvar=''
        (( ++i ))
    done
    emit_metric "$SIZE"
}

run_double() {
    local i=0
    local newvar

    while (( i < SIZE )); do
        # Double-quoted literal: bash scans every char for $ ` \ ! (none found, no substitution)
        newvar=""
        (( ++i ))
    done
    emit_metric "$SIZE"
}

case "$MODE" in
  single) run_single ;;
  double) run_double ;;
  *)
    printf 'Usage: %s --mode {single|double} [--size N] [--min-runtime T]\n' "$0" >&2
    exit 1
    ;;
esac
